package main

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

type Book struct {
	Title  string
	Author string
	Year   int
}

func (b Book) String() string {
	return fmt.Sprintf("%s by %s (%d)", b.Title, b.Author, b.Year)
}

type Library struct {
	books []Book
}

func (l *Library) Add(b Book) {
	l.books = append(l.books, b)
}

func (l *Library) Find(title string) (Book, error) {
	for _, b := range l.books {
		if b.Title == title {
			return b, nil
		}
	}
	return Book{}, errors.New("not found: " + title)
}

// Report lists the books oldest first, one per line, numbered from 1:
// 1. Title by Author (Year)
func (l *Library) Report() string {
	_ = sort.Slice
	_ = strings.Join
	return ""
}

func main() {
	lib := &Library{}
	lib.Add(Book{"Go", "Gopher", 2009})
	lib.Add(Book{"Malleshwari", "Rachakonda", 1950})
	fmt.Println(lib.Report())
}

